-- Re-seed menu_items.ingredients / .tags with richer, per-item multi-term data.
-- Root cause fix: the 20260830152020 KMUTT seed only ever wrote ONE generic
-- ingredient word per item and left tags empty on all 500 rows, which collapsed
-- the TF-IDF vocabulary used by recommend-similar / recommend-for-you down to
-- ~20 terms total -- same-category items became scalar-identical vectors and
-- every "Similar Foods" / "Recommended For You" result scored cosine ~1.0,
-- regardless of actual dish similarity. Terms below are keyword-extracted from
-- each item's existing name/description/category/spice_level/dietary flags --
-- same fields ml/recommend.py's build_food_vectors() expects -- so real
-- differentiation exists between items again.
update public.menu_items as m
set ingredients = v.ingredients, tags = v.tags
from (values
  ('001f1aac-42d0-412c-b9b4-e20d7e359e46'::uuid, ARRAY['beverages']::text[], ARRAY['smoothie','mild','halal','vegetarian','jay','beverages']::text[]),
